fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    assert_eq!(x1.len(), x2.len(), "input vectors must have the same length");

    let mut out = Vec::with_capacity(x1.len());
    for i in 0..x1.len() {
        let a = x1[i];
        let b = x2[i];
        let r = a & b;

        // Basic properties (checked per element)
        debug_assert_eq!(r, a & b);
        debug_assert_eq!(a & b, b & a); // commutative
        debug_assert_eq!(a & 0u8, 0u8); // and with zero
        debug_assert_eq!(a & a, a);     // idempotent
        debug_assert!(r <= a);
        debug_assert!(r <= b);

        out.push(r);
    }
    out
}